	/**
	* BitsName: tx3_pr_phase_control_profile7
	* Description: Phase control code for the tx3
	*
	*
	* For example, programming code 1 or 2 results in the following phase shift
	* 000001 : 360/64 *1 = 5.625 degree
	* 000010 : 360/64 *2 = 11.25 degree
	* Read/Write: RW
	* Bits: [25:20]
	* ResetValue: 0b000000
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx3PrPhaseControlProfile7 : 6;        /*## attribute Tx3PrPhaseControlProfile7 */
	/**
	* BitsName: Reserved_1
	* Description: not used
	*/
