/**
* R2M04_ChirpProfilePseudoRandomControlBits_t
* RegisterName: CHIRP_PROFILE_PSEUDO_RANDOM_CONTROL
* Profile selection can be based on pseudo random. The initial seed value is programmed in the register. The pseudo random profile generation is based on the LFSR (Linear  Feedback Shift Register).
*
* The profile number is based on the following equation
*
* r_LFSR_out = r_LFSR[3:1] ^ {r_LFSR[9],r_LFSR[9],r_LFSR[9] (shown below in the picture)
*
* The rest of the profile controls are still applicable and used from the register chirp_global_control. Only profile 0 to profile 7 is used in the pseudo random profile
*
*
*
*
*
*
*
* Address: 0x11C
* ResetValue: 0x0000468A
* Read/Write: RW
* FuSa: No
*/
typedef struct  {
	/**
	* BitsName: Reserved_0
	* Description: not used
	*/
	uint32_t Reserved0 : 16;        /*## attribute Reserved0 */
	/**
	* BitsName: profile_pseudo_random_seed
	* Description: The initial seed value programmed at the start of the chirp sequence.
	*
	* For the given seed, the profile is always consistent with chirp to chirp.
	*
	* Note1: Incase of no new seed value programmed at the start of the sequence, the previous LFSR operation would continue across the sequence.
	*
	* Note2: After 2^16-1 LFSR operation, the same LFSR pattern (the initial seed pattern) would continue
	*
	* Note3: Incase of profile_reset is set at global control register, the seed value will be reset to the programmed value in this register
	*
	* Read/Write: RW
	* Bits: [15:0]
	* ResetValue: 0b0100011010001010
	* Source: Application
	* FuSa: No
	*/
	uint32_t ProfilePseudoRandomSeed : 16;        /*## attribute ProfilePseudoRandomSeed */
}R2M04_ChirpProfilePseudoRandomControlBits_t;
/**
* R2M04_TxPrDdmaControlBits_t
* RegisterName: TX_PR_DDMA_CONTROL
* This register controls the DDMA steps (Indirectly the update rate of the phase). The accumulated integer (upper 6 bits) are driven towards the phase rotator
*
* Note: The update rate of the DDMA is controlled by the step phase
* Address: 0x120
* ResetValue: 0x00000000
* Read/Write: RW
* FuSa: No
*/
typedef struct  {
	/**
	* BitsName: ddma_mode_control
	* Description: The control decides whether ddma is enabled for operation and configured for the functional mode or test mode
	*
	* 00 : DDMA is disabled
	* 01 : DDMA in functional mode i.e the phase code step is incremented every chirp basis
	* 10 : DDMA in test mode i.e the phase code step is incremented within every chirp i.e at every clock cycle of 40MHz
	* 11 : DDMA in test mode with non-chirp mode (CW). DDMA starts as soon as this value is written in non-chirp mode
	*
	* Note: The phase code slope/update rate is determined by fractional steps defined in this register
	*
	*
	* Read/Write: RW
	* Bits: [31:30]
	* ResetValue: 0b00
	* Source: Application
	* FuSa: No
	*/
	uint32_t DdmaModeControl : 2;        /*## attribute DdmaModeControl */
	/**
	* BitsName: tx3_pr_ddma_step_phase
	* Description: TX1 PR icremental phase step is defined by this control. This value is integrated with TX_PR_DDMA_INIT_PHASE value and the MSB 6 bits are considered for the final phase
	*
	*
	* Case 1: For example, to have a phase code of 63, 62,61, 60, ...., the following to be programmed.
	*
	* tx*_pr_ddma_init_phase   = 0000000000 ('h000)
	* tx*_pr_ddma_step_phase = 1111110000 ('h3F0)
	*
	*
	* Case 2: For example, to have a phase code of 0, 1, 2, 3, ...., the following to be programmed
	*
	* tx*_pr_ddma_init_phase   =  0000000000 ('h000)
	* tx*_pr_ddma_step_phase = 0000010000 ('h010)
	*
	*
	* Case 3: For example, to have a phase code of 0, 1, 2, 3, ...., with the phase update rate every 16 chirps/cycles of 40 MHz, the following to be programmed
	*
	* tx*_pr_ddma_init_phase   =  0000000000 ('h000)
	* tx*_pr_ddma_step_phase =  0000000001 ('h001)
	*
	* In this case, phase code 0 is maintained for first 16 clocks, phase code 1 is maintained for next 16 clock cycles, phase code 2 ...
	*
	* Note1: In the case 1 & 2, the phase code is updated for every chirp or every clock basis, depending on the ddma_mode_control bit value (in the same register).
	*
	* Note 2: In the case 3, the phase code is updated for every 16 chirp or for every 16 clock cycle basis, depending on the ddma_mode_control bit value (in the same register).
	*
	* Note 3: With other combinations of tx*_pr_ddma_init_phase and tx*_pr_ddma_step_phase, required phase code value/update rate can be derived
	*
	* Read/Write: RW
	* Bits: [29:20]
	* ResetValue: 0b0000000000
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx3PrDdmaStepPhase : 10;        /*## attribute Tx3PrDdmaStepPhase */
	/**
	* BitsName: tx2_pr_ddma_step_phase
	* Description: TX1 PR icremental phase step is defined by this control. This value is integrated with TX_PR_DDMA_INIT_PHASE value and the MSB 6 bits are considered for the final phase
	*
	*
	* Case 1: For example, to have a phase code of 63, 62,61, 60, ...., the following to be programmed.
	*
	* tx*_pr_ddma_init_phase   = 0000000000 ('h000)
	* tx*_pr_ddma_step_phase = 1111110000 ('h3F0)
	*
	*
	* Case 2: For example, to have a phase code of 0, 1, 2, 3, ...., the following to be programmed
	*
	* tx*_pr_ddma_init_phase   =  0000000000 ('h000)
	* tx*_pr_ddma_step_phase = 0000010000 ('h010)
	*
	*
	* Case 3: For example, to have a phase code of 0, 1, 2, 3, ...., with the phase update rate every 16 chirps/cycles of 40 MHz, the following to be programmed
	*
	* tx*_pr_ddma_init_phase   =  0000000000 ('h000)
	* tx*_pr_ddma_step_phase =  0000000001 ('h001)
	*
	* In this case, phase code 0 is maintained for first 16 clocks, phase code 1 is maintained for next 16 clock cycles, phase code 2 ...
	*
	* Note1: In the case 1 & 2, the phase code is updated for every chirp or every clock basis, depending on the ddma_mode_control bit value (in the same register).
	*
	* Note 2: In the case 3, the phase code is updated for every 16 chirp or for every 16 clock cycle basis, depending on the ddma_mode_control bit value (in the same register).
	*
	* Note 3: With other combinations of tx*_pr_ddma_init_phase and tx*_pr_ddma_step_phase, required phase code value/update rate can be derived
	*
	* Read/Write: RW
	* Bits: [19:10]
	* ResetValue: 0b0000000000
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx2PrDdmaStepPhase : 10;        /*## attribute Tx2PrDdmaStepPhase */
	/**
	* BitsName: tx1_pr_ddma_step_phase
	* Description: TX1 PR incremental phase step is defined by this control. This value is integrated with TX_PR_DDMA_INIT_PHASE value and the MSB 6 bits are considered for the final phase
	*
	*
	* Case 1: For example, to have a phase code of 63, 62,61, 60, ...., the following to be programmed.
	*
	* tx*_pr_ddma_init_phase   = 0000000000 ('h000)
	* tx*_pr_ddma_step_phase = 1111110000 ('h3F0)
	*
	*
	* Case 2: For example, to have a phase code of 0, 1, 2, 3, ...., the following to be programmed
	*
	* tx*_pr_ddma_init_phase   =  0000000000 ('h000)
	* tx*_pr_ddma_step_phase = 0000010000 ('h010)
	*
	*
	* Case 3: For example, to have a phase code of 0, 1, 2, 3, ...., with the phase update rate every 16 chirps/cycles of 40 MHz, the following to be programmed
	*
	* tx*_pr_ddma_init_phase   =  0000000000 ('h000)
	* tx*_pr_ddma_step_phase =  0000000001 ('h001)
	*
	* In this case, phase code 0 is maintained for first 16 clocks, phase code 1 is maintained for next 16 clock cycles, phase code 2 ...
	*
	* Note1: In the case 1 & 2, the phase code is updated for every chirp or every clock basis, depending on the ddma_mode_control bit value (in the same register).
	*
	* Note 2: In the case 3, the phase code is updated for every 16 chirp or for every 16 clock cycle basis, depending on the ddma_mode_control bit value (in the same register).
	*
	* Note 3: With other combinations of tx*_pr_ddma_init_phase and tx*_pr_ddma_step_phase, required phase code value/update rate can be derived
	*
	* Read/Write: RW
	* Bits: [9:0]
	* ResetValue: 0b0000000000
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx1PrDdmaStepPhase : 10;        /*## attribute Tx1PrDdmaStepPhase */
}R2M04_TxPrDdmaControlBits_t;
/**
* R2M04_TxPrChirpControlModesBits_t
* RegisterName: TX_PR_CHIRP_CONTROL_MODES
* This register controls the final phase code generation + BPSK, asynchronous/synchronous phase changes etc
*
* In Stage 1, control decides the phase code is either from Profile or DDMA
* In Stage 2, control decides the phase code msb bits are overriden/replaced by QPSK[1:0] from IO to have steps of 90 degree phase shifts or not
* In Stage 3, control decides the phase code can be integrated with QPSK[1:0] bits or not
* In Stage 4, control decides the BPSK (180 degree phase shift) is controlled either from Profile or from QPSK[0] IO pin along with final phase code
* Address: 0x124
* ResetValue: 0x00000000
* Read/Write: RW
* FuSa: No
*/
typedef struct  {
	/**
	* BitsName: Reserved_0
	* Description: not used
	*/
	uint32_t Reserved0 : 15;        /*## attribute Reserved0 */
	/**
	* BitsName: reset_ddma
	* Description: The control to reset the DDMA phase accumulation . This is an Auto-clear bit
	*
	* 0:  No action
	* 1:  Reset/Reload the DDMA accumulator. The values after reset will be from register TX_PR_DDMA_CONTROL(Step), TX_PR_DDMA_INIT_PHASE (Init)
	*
	* Note: The phase code coming from profile will use profile reset located in CHIRP_GLOBAL_CONTROL register, field enable_profile_reset.
	* USEMODE: Every frame this bit is required to be set to reset the DDMA phase
	* Read/Write: W
	* Bits: [16]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t ResetDdma : 1;        /*## attribute ResetDdma */
	/**
	* BitsName: Reserved_1
	* Description: not used
	*/
	uint32_t Reserved1 : 2;        /*## attribute Reserved1 */
	/**
	* BitsName: qpsk_io_async_enable
	* Description: The control to asynchronously sample the QPSK IO as it comes from external MCU/Chip to the chip.
	*
	* 0:  QPSK inputs from IOs are sampled synchronous with defined timing points i.e phase changes are treated the same way as the phase code values coming from profile registers and any asynchronous changes are masked. This means the IO changes are sampled once per chirp with the timing points derived from TIMING_CONTROL_1_PROFILE* and rest of the time IO changes are masked. The total delay involved before the phase change reaches the final stage of the TX is maximum of 100 ns (4 cycles of 25 ns)
	*
	* 1:  QPSK inputs from IOs are sampled asynchronous as it is driven by external MCU/Chip. This means the IO changes are continuously sampled during the chirp as it changes.  The total delay involved before the phase change reaches the final stage of the TX is maximum of  100 ns (4 cycles of 25 ns)
	*
	* Read/Write: RW
	* Bits: [13]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t QpskIoAsyncEnable : 1;        /*## attribute QpskIoAsyncEnable */
	/**
	* BitsName: bpsk_io_async_enable
	* Description: The control to asynchronously sample the BPSK IO as it comes from external MCU/Chip to the chip.
	*
	* 0:  BPSK inputs from IOs are sampled synchronous with defined timing points i.e phase changes are treated the same way as the BPSK values coming from profile registers and any asynchronous changes are masked. This means the IO changes are sampled once per chirp with the timing points derived from TIMING_CONTROL_1_PROFILE* and rest of the time IO changes are masked. The total delay involved before the phase change reaches the final stage of the TX is maximum of 100 ns (4 cycles of 25 ns)
	*
	* 1:  BPSK inputs from IOs are sampled asynchronous as it is driven by external MCU/Chip. This means the IO changes are continuously sampled during the chirp as it changes.  The total delay involved before the phase change reaches the final stage of the TX is maximum of 100 ns (4 cycles of 25 ns)
	*
	* Read/Write: RW
	* Bits: [12]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t BpskIoAsyncEnable : 1;        /*## attribute BpskIoAsyncEnable */
	/**
	* BitsName: tx3_pr_phase_bpsk_control
	* Description: The control to select the BPSK control bit either from Profile or from QPSK control bit (bit 0) from IO. This is independent of the phase code and directy controls the 0 or 180 degree phase shift of the BPSK modulator
	*
	* 0:  BPSK control bit from profile i.e TIMING_CONTROL_1_PROFILE* registers
	* 1:  BPSK control bit from QPSK[0] IO pin
	*
	* Read/Write: RW
	* Bits: [11]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx3PrPhaseBpskControl : 1;        /*## attribute Tx3PrPhaseBpskControl */
	/**
	* BitsName: tx3_pr_phase_add_qpsk_control
	* Description: Stage3/Final  phase code
	*
	* The control to add the phase code (either from profile or from DDMA) with QPSK control bits from IO to generate the stage3 final phase code towards PR
	*
	* 0:  Phase code from stage2 i.e based on the setting tx3_pr_phase_msb_replace_with_qpsk_control
	* 1:  Phase code is added with QPSK bits i.e Final phase code = phase code [5:0] + {QPSK[1:0], 0000}
	*
	* Note1: The QPSK bits from IO is left shifted by 4 and added to the phase code coming from profile or DDMA
	*
	* Read/Write: RW
	* Bits: [10]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx3PrPhaseAddQpskControl : 1;        /*## attribute Tx3PrPhaseAddQpskControl */
	/**
	* BitsName: tx3_pr_phase_msb_replace_with_qpsk_control
	* Description: Stage2 phase code
	*
	* The control to replace the phase code (either from profile or from DDMA) with QPSK control bits from IO to generate the stage2 phase code
	*
	* 0: No mix of phase code and QPSK bits i.e the actual phase code either from profile or ddma is driven towards stage 2 phase code
	* 1: Upper 2 bits (MSB) of the phase code is replaced by QPSK bits i.e second stage of phase code = {QPSK[1], QPSK[0], phase code[3:0]}
	*
	*
	*
	* Read/Write: RW
	* Bits: [9]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx3PrPhaseMsbReplaceWithQpskControl : 1;        /*## attribute Tx3PrPhaseMsbReplaceWithQpskControl */
	/**
	* BitsName: tx3_pr_phase_control
	* Description: Stage1 phase code
	*
	* The control to select the phase code from profile or from DDMA to generate the stage1 phase code
	*
	* 0:  The 6bit phase code is selected from Profiles i.e TIMING_CONTROL_4_PROFILE* registers
	* 1 : The 6bit phase code is selected from DDMA i.e TX_PR_DDMA_CONTROL register
	*
	* Read/Write: RW
	* Bits: [8]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx3PrPhaseControl : 1;        /*## attribute Tx3PrPhaseControl */
	/**
	* BitsName: tx2_pr_phase_bpsk_control
	* Description: The control to select the BPSK control bit either from Profile or from QPSK control bit (bit 0) from IO. This is independent of the phase code and directy controls the 0 or 180 degree phase shift of BPSK modulator
	*
	* 0:  BPSK control bit from profile i.e TIMING_CONTROL_1_PROFILE* registers
	* 1:  BPSK control bit from QPSK[0] IO pin
	*
	* Read/Write: RW
	* Bits: [7]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx2PrPhaseBpskControl : 1;        /*## attribute Tx2PrPhaseBpskControl */
	/**
	* BitsName: tx2_pr_phase_add_qpsk_control
	* Description: Stage3/Final  phase code
	*
	* The control to add the phase code (either from profile or from DDMA) with QPSK control bits from IO to generate the stage3 final phase code towards PR
	*
	* 0:  Phase code from stage2 i.e based on the setting tx2_pr_phase_msb_replace_with_qpsk_control
	* 1:  Phase code is added with QPSK bits i.e Final phase code = phase code [5:0] + {QPSK[1:0], 0000}
	*
	* Note1: The QPSK bits from IO is left shifted by 4 and added to the phase code coming from profile or DDMA
	*
	* Read/Write: RW
	* Bits: [6]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx2PrPhaseAddQpskControl : 1;        /*## attribute Tx2PrPhaseAddQpskControl */
	/**
	* BitsName: tx2_pr_phase_msb_replace_with_qpsk_control
	* Description: Stage2 phase code
	*
	* The control to replace the phase code (either from profile or from DDMA) with QPSK control bits from IO to generate the stage2 phase code
	*
	* 0: No mix of phase code and QPSK bits i.e the actual phase code either from profile or ddma is driven towards stage 2 phase code
	* 1: Upper 2 bits (MSB) of the phase code is replaced by QPSK bits i.e second stage of phase code = {QPSK[1], QPSK[0], phase code[3:0]}
	*
	*
	*
	* Read/Write: RW
	* Bits: [5]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx2PrPhaseMsbReplaceWithQpskControl : 1;        /*## attribute Tx2PrPhaseMsbReplaceWithQpskControl */
	/**
	* BitsName: tx2_pr_phase_control
	* Description: Stage1 phase code
	*
	* The control to select the phase code from profile or from DDMA to generate the stage1 phase code
	*
	* 0:  The 6bit phase code is selected from Profiles i.e TIMING_CONTROL_4_PROFILE* registers
	* 1 : The 6bit phase code is selected from DDMA i.e TX_PR_DDMA_CONTROL register
	*
	* Read/Write: RW
	* Bits: [4]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx2PrPhaseControl : 1;        /*## attribute Tx2PrPhaseControl */
	/**
	* BitsName: tx1_pr_phase_bpsk_control
	* Description: The control to select the BPSK control bit either from Profile or from QPSK control bit (bit 0) from IO. This is independent of the phase code and directy controls the 0 or 180 degree phase shift of BPSK modulator
	*
	* 0:  BPSK control bit from profile i.e TIMING_CONTROL_1_PROFILE* registers
	* 1:  BPSK control bit from QPSK[0] IO pin
	*
	* Read/Write: RW
	* Bits: [3]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx1PrPhaseBpskControl : 1;        /*## attribute Tx1PrPhaseBpskControl */
	/**
	* BitsName: tx1_pr_phase_add_qpsk_control
	* Description: Stage3/Final phase code
	*
	* The control to add the phase code (either from profile or from DDMA) with QPSK control bits from IO to generate the stage3 final phase code towards PR
	*
	* 0:  Phase code from stage2 i.e based on the setting tx1_pr_phase_msb_replace_with_qpsk_control
	* 1:  Phase code is added with QPSK bits i.e Final phase code = phase code [5:0] + {QPSK[1:0], 0000}
	*
	* Note1: The QPSK bits from IO is left shifted by 4 and added to the phase code coming from profile or DDMA
	*
	* Read/Write: RW
	* Bits: [2]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx1PrPhaseAddQpskControl : 1;        /*## attribute Tx1PrPhaseAddQpskControl */
	/**
	* BitsName: tx1_pr_phase_msb_replace_with_qpsk_control
	* Description: Stage2 phase code
	*
	* The control to replace the phase code (either from profile or from DDMA) with QPSK control bits from IO to generate the stage2 phase code
	*
	* 0: No mix of phase code and QPSK bits i.e the actual phase code either from profile or ddma is driven towards stage 2 phase code
	* 1: Upper 2 bits (MSB) of the phase code is replaced by QPSK bits i.e second stage of phase code = {QPSK[1], QPSK[0], phase code[3:0]}
	*
	*
	*
	* Read/Write: RW
	* Bits: [1]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx1PrPhaseMsbReplaceWithQpskControl : 1;        /*## attribute Tx1PrPhaseMsbReplaceWithQpskControl */
	/**
	* BitsName: tx1_pr_phase_control
	* Description: Stage1 phase code
	*
	* The control to select the phase code from profile or from DDMA to generate the stage1 phase code
	*
	* 0:  The 6bit phase code is selected from Profiles i.e TIMING_CONTROL_4_PROFILE* registers
	* 1 : The 6bit phase code is selected from DDMA i.e TX_PR_DDMA_CONTROL register
	*
	* Read/Write: RW
	* Bits: [0]
	* ResetValue: 0b0
	* Source: Application
	* FuSa: No
	*/
	uint32_t Tx1PrPhaseControl : 1;        /*## attribute Tx1PrPhaseControl */
}R2M04_TxPrChirpControlModesBits_t;
